using System.Net;
using System.Net.Http.Json;
using System.Text.Json.Serialization;
using ApexPost.Client;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

// Console consumer of the generated ApexPost API client (ApexPost.Client, generated by NSwag from contracts/v2.json).
// Every step below is a REAL HTTP call to the running API (default https://localhost:54402/).
//
//   1. start the API:  dotnet run --project src/ApexPost.Api       (Development; set the user-secrets first, see README)
//   2. run this tool:  dotnet run --project tools/ApexPost.Client.Consumer
//
// Settings (appsettings / environment / command line): Api:BaseAddress, Api:CourierId.

var builder = Host.CreateApplicationBuilder(args);

var baseAddress = new Uri(builder.Configuration["Api:BaseAddress"] ?? "https://localhost:54402/");
var courierId = builder.Configuration["Api:CourierId"] ?? "COURIER-001";

builder.Services.AddSingleton(new ConsumerOptions(baseAddress, courierId));
builder.Services.AddHttpClient(AccessTokenProvider.HttpClientName, client => client.BaseAddress = baseAddress);
builder.Services.AddSingleton<AccessTokenProvider>();
builder.Services.AddTransient<BearerTokenHandler>();
builder.Services.AddApexPostClient(baseAddress).AddHttpMessageHandler<BearerTokenHandler>();

using var host = builder.Build();

var logger = host.Services.GetRequiredService<ILogger<ConsumerOptions>>();
var client = host.Services.GetRequiredService<IApexPostClient>();

logger.LogInformation("ApexPost client consumer -> {BaseAddress} as {CourierId}", baseAddress, courierId);

try
{
    // ---- 1. create a shipment (POST /api/v2/shipments) -----------------------------------------
    var created = await CreateShipmentAsync(client, logger);
    logger.LogInformation("Created {TrackingNumber}, status {Status}, recipient {Recipient}",
        created.TrackingNumber, created.Status, created.Recipient.Name);

    // ---- 2. read it back (GET /api/v2/shipments/{trackingNumber}) ------------------------------
    var fetched = await client.GetShipmentAsync(created.TrackingNumber);
    logger.LogInformation("Fetched {TrackingNumber}: {City}, {Count} scan(s)",
        fetched.TrackingNumber, fetched.Recipient.City, fetched.Scans.Count);

    // ---- 3. upload offline scans (POST .../scans), twice: the second call is all duplicates -----
    var scans = BuildScans(courierId);
    var first = await client.UploadScansAsync(created.TrackingNumber, new ScanUploadRequest { Scans = scans });
    logger.LogInformation("Upload #1: accepted={Accepted} duplicates={Duplicates} rejected={Rejected}",
        first.Accepted, first.DuplicatesSkipped, first.Rejected);

    var second = await client.UploadScansAsync(created.TrackingNumber, new ScanUploadRequest { Scans = scans });
    logger.LogInformation("Upload #2 (same scan ids): accepted={Accepted} duplicates={Duplicates} rejected={Rejected}",
        second.Accepted, second.DuplicatesSkipped, second.Rejected);

    // ---- 4. scan history and the latestScan summary of the v2 detail ---------------------------
    var history = await client.GetScanHistoryAsync(created.TrackingNumber);
    var detail = await client.GetShipmentAsync(created.TrackingNumber);
    logger.LogInformation("History has {Count} scan(s); latest scan: {ScanType} at {Location}",
        history.Count, detail.LatestScan?.ScanType, detail.LatestScan?.Location);

    // ---- 5. paged list (GET /api/v2/shipments) --------------------------------------------------
    var page = await client.GetShipmentsAsync(page: 1, pageSize: 5, status: null, city: null, courierId: null, fromDate: null, toDate: null);
    logger.LogInformation("List page {Page}: {Count} of {Total} shipment(s)", page.Page, page.Items.Count, page.TotalCount);

    // ---- 6. error handling: 404 problem details -------------------------------------------------
    try
    {
        await client.GetShipmentAsync("APX-19990101");
    }
    catch (ApiException<ProblemDetails> ex) when (ex.StatusCode == (int)HttpStatusCode.NotFound)
    {
        logger.LogInformation("404 handled: {Title} - {Detail}", ex.Result.Title, ex.Result.Detail);
    }

    // ---- 7. error handling: 400 validation problem details ---------------------------------------
    try
    {
        await client.CreateShipmentAsync(new CreateShipmentRequest
        {
            TrackingNumber = "NOT-A-TRACKING-NUMBER",
            WeightKg = 500,
            RecipientName = "x",
            RecipientPhone = "123",
            RecipientAddress = "x",
            RecipientCity = "x"
        });
    }
    catch (ApiException<ValidationProblemDetails> ex)
    {
        foreach (var (field, messages) in ex.Result.Errors)
        {
            logger.LogInformation("400 handled: {Field}: {Messages}", field, string.Join("; ", messages));
        }
    }

    logger.LogInformation("Done.");
    return 0;
}
catch (ApiException ex)
{
    logger.LogError("API call failed with HTTP {StatusCode}: {Message}", ex.StatusCode, ex.Message);
    return 1;
}
catch (HttpRequestException ex)
{
    logger.LogError(ex, "Could not reach the API at {BaseAddress}. Is it running?", baseAddress);
    return 2;
}

static async Task<V2ShipmentDetail> CreateShipmentAsync(IApexPostClient client, ILogger logger)
{
    // Tracking numbers are APX-NNNNNNNN; pick a random past date and retry on the (unlikely) 409.
    for (var attempt = 1; ; attempt++)
    {
        var trackingNumber = "APX-" + DateTime.UtcNow.Date.AddDays(-Random.Shared.Next(1, 2000)).ToString("yyyyMMdd");
        try
        {
            return await client.CreateShipmentAsync(new CreateShipmentRequest
            {
                TrackingNumber = trackingNumber,
                WeightKg = 2.5,
                RecipientName = "John Doe",
                RecipientPhone = "+15551234567",
                RecipientAddress = "123 Main St",
                RecipientCity = "Springfield",
                RecipientPostalCode = "12345",
                RecipientCountry = "US",
                SpecialInstructions = "Leave at door"
            });
        }
        catch (ApiException<ProblemDetails> ex) when (ex.StatusCode == (int)HttpStatusCode.Conflict && attempt < 5)
        {
            logger.LogInformation("{TrackingNumber} already exists, trying another", trackingNumber);
        }
    }
}

static List<ScanDocumentRequest> BuildScans(string courierId)
{
    var now = DateTimeOffset.UtcNow;
    return
    [
        new ScanDocumentRequest
        {
            ScanId = $"scan::{Guid.NewGuid()}",
            ScanType = ScanType.Pickup,
            CourierId = courierId,
            Location = "Warehouse A",
            ScannedAtUtc = now.AddMinutes(-1),
            Notes = "Picked up"
        },
        new ScanDocumentRequest
        {
            ScanId = $"scan::{Guid.NewGuid()}",
            ScanType = ScanType.InTransit,
            CourierId = courierId,
            Location = "Distribution Center",
            ScannedAtUtc = now,
            Notes = "In transit"
        }
    ];
}

/// <summary>Settings of the consumer.</summary>
internal sealed record ConsumerOptions(Uri BaseAddress, string CourierId);

/// <summary>
/// Gets a JWT for the configured courier from the API's Development-only token endpoint and caches it.
/// (A production app would sign in with its identity provider instead.)
/// </summary>
internal sealed class AccessTokenProvider(IHttpClientFactory httpClientFactory, ConsumerOptions options)
{
    public const string HttpClientName = "dev-token";

    private readonly SemaphoreSlim _gate = new(1, 1);
    private string? _token;

    public async Task<string> GetTokenAsync(CancellationToken cancellationToken)
    {
        if (_token is not null)
        {
            return _token;
        }

        await _gate.WaitAsync(cancellationToken);
        try
        {
            if (_token is null)
            {
                var http = httpClientFactory.CreateClient(HttpClientName);
                var response = await http.PostAsJsonAsync(
                    "/dev/token", new { courierId = options.CourierId, role = "Courier" }, cancellationToken);
                response.EnsureSuccessStatusCode();

                var body = await response.Content.ReadFromJsonAsync<TokenBody>(cancellationToken)
                    ?? throw new InvalidOperationException("The token endpoint returned an empty body.");
                _token = body.AccessToken;
            }

            return _token;
        }
        finally
        {
            _gate.Release();
        }
    }

    private sealed record TokenBody([property: JsonPropertyName("access_token")] string AccessToken);
}

/// <summary>Adds the Bearer token to every request of the generated client.</summary>
internal sealed class BearerTokenHandler(AccessTokenProvider tokens) : DelegatingHandler
{
    protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken cancellationToken)
    {
        var token = await tokens.GetTokenAsync(cancellationToken);
        request.Headers.Authorization = new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", token);
        return await base.SendAsync(request, cancellationToken);
    }
}
